def total(n):
    result = 0
    for value in range(n):
        result += value
    return result

def loop_else_complete(n):
    result = []
    for value in range(n):
        result.append(value)
    else:
        result.append("done")
    return result

def loop_else_break(n):
    result = []
    for value in range(n):
        if value == 2:
            break
        result.append(value)
    else:
        result.append("done")
    return result
